import{_ as a,o as e,c as o,a2 as r}from"./chunks/framework.Dh6DF7gt.js";const _=JSON.parse('{"title":"自动化场景","description":"以场景而不是设备为中心设计、测试和维护自动化规则。","frontmatter":{"title":"自动化场景","description":"以场景而不是设备为中心设计、测试和维护自动化规则。"},"headers":[],"relativePath":"implementation/automation.md","filePath":"implementation/automation.md","lastUpdated":1785475798000}'),d={name:"implementation/automation.md"};function i(n,t,l,s,c,m){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="自动化场景" tabindex="-1">自动化场景 <a class="header-anchor" href="#自动化场景" aria-label="Permalink to &quot;自动化场景&quot;">​</a></h1><h2 id="场景模板" tabindex="-1">场景模板 <a class="header-anchor" href="#场景模板" aria-label="Permalink to &quot;场景模板&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>场景名称</td><td>如：会议室自动进入会议模式</td></tr><tr><td>触发条件</td><td>人体存在、预约开始、墙面开关、时间段</td></tr><tr><td>执行动作</td><td>灯光、窗帘、空调、屏幕、通知</td></tr><tr><td>安全边界</td><td>允许自动关，禁止自动开；手动优先</td></tr><tr><td>回退机制</td><td>平台/网络故障时，实体开关仍可用</td></tr><tr><td>测试证据</td><td>测试日期、环境、结果、关联 Issue</td></tr></tbody></table><h2 id="最小可行场景" tabindex="-1">最小可行场景 <a class="header-anchor" href="#最小可行场景" aria-label="Permalink to &quot;最小可行场景&quot;">​</a></h2><ol><li><strong>下班节能</strong>：无人状态下关闭非必要照明和显示设备。</li><li><strong>会议模式</strong>：预约或手动触发后调整照明、屏幕和空调。</li><li><strong>环境提醒</strong>：CO₂、温湿度或漏水达到阈值时推送告警。</li></ol><div class="warning custom-block"><p class="custom-block-title">先测试再上线</p><p>自动化第一次启用时应设定观察期，避免因误触发影响办公。涉及门禁、消防和人身安全的系统不得由普通自动化规则直接控制。</p></div>',6)])])}const p=a(d,[["render",i]]);export{_ as __pageData,p as default};
